import { existsSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

/**
 * Studio brand images: src/assets/brand/{currawong,client}/ -> src/config/studio-brand/assets.generated.ts,
 * a map from each image's repo path (the value used in studio-brand.json) to its imported module.
 * studio-brand.json holds paths as plain text, which a bundler can't follow, so this is the one place
 * the images are imported. No dependencies; `npm run brand-assets` (also run by `predev` and `typegen`).
 * The generated file is committed; a unit test fails when it is stale.
 */

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
export const paths = {
  out: join(root, 'src/config/studio-brand/assets.generated.ts'),
  dirs: ['src/assets/brand/currawong', 'src/assets/brand/client'],
}

const IMAGE = /\.(svg|png|webp|jpe?g|avif)$/i

/** Every image under the brand folders, as repo-relative paths, sorted so the output is stable. */
export function listBrandImages(base = root) {
  return paths.dirs
    .flatMap((dir) =>
      existsSync(join(base, dir))
        ? readdirSync(join(base, dir))
            .filter((file) => IMAGE.test(file))
            .map((file) => `${dir}/${file}`)
        : [],
    )
    .sort()
}

/** The TypeScript source for a list of repo-relative image paths. */
export function buildAssets(images) {
  const lines = [
    '// Generated by scripts/build-studio-brand-assets.mjs from src/assets/brand/. Do not edit; run `npm run brand-assets`.',
    '',
  ]
  images.forEach((image, index) => {
    lines.push(`import image${index} from '../../${image.replace(/^src\//, '')}'`)
  })
  lines.push(
    '',
    "/** What a bundler gives an image import: Next.js an object with `src`, Sanity's Vite build a URL string. */",
    'export type BrandImage = string | { src: string; width?: number; height?: number }',
    '',
    'export const brandAssets: Record<string, BrandImage> = {',
  )
  images.forEach((image, index) => lines.push(`  '${image}': image${index},`))
  lines.push('}', '')
  return lines.join('\n')
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const images = listBrandImages()
  writeFileSync(paths.out, buildAssets(images))
  console.log(`Studio brand assets: wrote assets.generated.ts (${images.length} images)`)
}
